import type { Readable } from 'node:stream'

/**
 * Object storage behind attachments. Routes and services only ever talk to
 * this interface; provider SDKs stay inside the adapters.
 *
 * Keys are generated by the API (`<workspaceId>/<yyyy>/<mm>/<uuid>.<ext>`),
 * never derived from user input.
 */
export interface ObjectStorage {
  readonly driver: 'local' | 's3' | 'memory'
  put(key: string, body: Buffer, contentType: string): Promise<void>
  delete(key: string): Promise<void>
  /**
   * How a client fetches the object once the API has checked access: a
   * short-lived signed URL to redirect to, or a stream the API serves itself.
   */
  access(key: string, options: AccessOptions): Promise<{ redirect: string } | { stream: Readable }>
  /** Cheap reachability check (readiness probe). */
  check(): Promise<void>
}

export interface AccessOptions {
  fileName: string
  contentType: string
  disposition: 'inline' | 'attachment'
}

/** RFC 6266 Content-Disposition with an ASCII fallback and the UTF-8 name. */
export function contentDisposition(disposition: 'inline' | 'attachment', fileName: string): string {
  const ascii = fileName.replace(/[^\x20-\x7e]/g, '_').replace(/["\\]/g, '_')
  return `${disposition}; filename="${ascii}"; filename*=UTF-8''${encodeURIComponent(fileName)}`
}

/** Keys are opaque, generated paths: lowercase id segments separated by `/`, plus an extension. */
export const STORAGE_KEY_PATTERN = /^[a-z0-9-]+(\/[a-z0-9-]+)*\.[a-z0-9]+$/

export function assertStorageKey(key: string): void {
  if (!STORAGE_KEY_PATTERN.test(key)) throw new Error(`Invalid storage key: ${key}`)
}
